<section class="page-hero container compact-hero"><div><?php breadcrumbs($category?['Каталог'=>'/catalog',$category['name']=>null]:['Каталог'=>null]) ?><span class="eyebrow">Подбор по спецификации</span><h1><?= e($category['name']??'Каталог продукции') ?></h1><p class="lead"><?= e($category['lead']??'Кабель, металлопрокат, профнастил и трансформаторное оборудование для вашего проекта.') ?></p><p class="support-copy">Выберите нужные позиции и укажите параметры в заявке. Наличие, стоимость и срок поставки подтверждаются в коммерческом предложении.</p><div class="hero-points"><span><?= number_format($total,0,',',' ') ?> позиций</span><span>Цена по запросу</span><span>Один запрос на все материалы</span></div></div><div class="hero-side"><img src="<?= e(image_url($category['image']??'assets/img/about.webp')) ?>" alt="<?= e($category['name']??'Продукция для комплексных поставок') ?>" width="1100" height="700" fetchpriority="high"></div></section>
<section class="section container catalog-search-block"><form class="search-box" method="get" action="<?= e(url($category?'/catalog/'.$category['slug']:'/catalog')) ?>"><span aria-hidden="true">⌕</span><input name="q" aria-label="Поиск товара" type="search" value="<?= e($q) ?>" placeholder="Марка, наименование или характеристика"><button class="btn btn-primary" type="submit">Найти</button></form></section>
<section class="section container catalog-section"><div class="catalog-layout"><aside class="catalog-aside"><h2>Разделы каталога</h2><a class="category-filter <?= !$category?'active':'' ?>" href="<?= url('/catalog') ?>">Все направления</a><?php foreach(roots() as $root): ?><a class="category-filter <?= $category&&($category['id']===$root['id']||$category['parent_id']===$root['id'])?'active':'' ?>" href="<?= url('/catalog/'.$root['slug']) ?>"><?= e($root['name']) ?></a><?php if($category&&($category['id']===$root['id']||$category['parent_id']===$root['id'])):foreach(rows('SELECT * FROM categories WHERE parent_id=? AND active=1 ORDER BY sort_order,id',[$root['id']]) as $child): ?><a class="category-filter child <?= $child['id']===$category['id']?'active':'' ?>" href="<?= url('/catalog/'.$child['slug']) ?>"><?= e($child['name']) ?></a><?php endforeach;endif;endforeach ?><div class="aside-help"><strong>Нужен подбор?</strong><p>Отправьте список материалов или технические требования.</p><a class="text-link" href="<?= url('/request') ?>">Оформить заявку →</a></div></aside><div class="catalog-results"><div class="catalog-toolbar"><p><?= $q?'По запросу «'.e($q).'»':'В каталоге' ?>: <strong><?= (int)$total ?></strong> позиций</p><form method="get"><input type="hidden" name="q" value="<?= e($q) ?>"><label>Порядок <select name="sort" data-autosubmit><option value="default" <?= $sort==='default'?'selected':'' ?>>По каталогу</option><option value="name" <?= $sort==='name'?'selected':'' ?>>По названию</option><option value="new" <?= $sort==='new'?'selected':'' ?>>Новые позиции</option></select></label><noscript><button type="submit">Применить</button></noscript></form></div><?php if($products): ?><div class="product-grid catalog-product-grid"><?php foreach($products as $p)product_card($p) ?></div><?php else: ?><div class="empty-state"><h2>Подходящие позиции не найдены</h2><p>Измените запрос или отправьте марку и характеристики менеджеру. Мы уточним возможность поставки.</p><a class="btn btn-primary" href="<?= url('/request') ?>">Отправить свой список</a></div><?php endif ?><?php if($lastPage>1): ?><nav class="pagination" aria-label="Страницы каталога"><?php if($currentPage>1): ?><a href="<?= e(url($path).'?'.http_build_query(['q'=>$q,'sort'=>$sort,'page'=>$currentPage-1])) ?>">← Назад</a><?php endif ?><?php for($i=max(1,$currentPage-2);$i<=min($lastPage,$currentPage+2);$i++): ?><a <?= $i===$currentPage?'aria-current="page"':'' ?> href="<?= e(url($path).'?'.http_build_query(['q'=>$q,'sort'=>$sort,'page'=>$i])) ?>"><?= $i ?></a><?php endfor ?><?php if($currentPage<$lastPage): ?><a href="<?= e(url($path).'?'.http_build_query(['q'=>$q,'sort'=>$sort,'page'=>$currentPage+1])) ?>">Далее →</a><?php endif ?></nav><?php endif ?></div></div><?php if($category&&$category['description_html']): ?><div class="detail-card prose category-copy"><?= rich($category['description_html']) ?></div><?php endif ?></section>
<?php include __DIR__.'/cta.php' ?>
